ALTER TABLE public.scam_alerts ADD COLUMN scam_type_es text, ADD COLUMN ai_recommendation_es text, ADD COLUMN scam_flags_es jsonb;
UPDATE public.scam_alerts SET scam_type_es = 'Suplantación del IRS o de un banco y estafa con tarjetas de regalo', ai_recommendation_es = 'No responda a este correo, no haga clic en ningún enlace ni compre tarjetas de regalo. Llame directamente a su banco al número que aparece en el reverso de su tarjeta de débito o crédito para confirmar que su cuenta está en orden.', scam_flags_es = '["⚠️ Afirma que su cuenta bancaria está bloqueada o suspendida para provocar pánico", "⚠️ Le pide su número de Seguro Social; ningún banco legítimo se lo pide por correo electrónico", "⚠️ Exige que compre tarjetas de regalo como pago, una señal típica de estafa", "⚠️ Usa la palabra URGENTE en mayúsculas para presionarle a actuar sin pensar", "⚠️ Los bancos legítimos nunca le pedirán por correo que envíe información personal o compre tarjetas de regalo"]'::jsonb WHERE scam_type = 'IRS/Bank Impersonation & Gift Card Scam';
COMMENT ON COLUMN public.scam_alerts.scam_type_es IS 'Formal Spanish translation of the generated English scam type; never user-entered content.';
COMMENT ON COLUMN public.scam_alerts.ai_recommendation_es IS 'Formal Spanish translation of the generated safety recommendation.';
COMMENT ON COLUMN public.scam_alerts.scam_flags_es IS 'Formal Spanish translations of generated warning flags.';